import os
from typing import Any, Dict, List, Optional


def _safe_get(obj: Any, *names: str, default=None):
    for name in names:
        if isinstance(obj, dict) and name in obj:
            return obj[name]
        if hasattr(obj, name):
            return getattr(obj, name)
    return default


def _to_number(value: Any):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return value
    text = str(value).strip()
    if not text:
        return None
    cleaned = "".join(ch for ch in text if ch.isdigit() or ch in ".-,")
    cleaned = cleaned.replace(",", "")
    try:
        if "." in cleaned:
            return float(cleaned)
        return int(cleaned)
    except ValueError:
        return text


def _extract_line_items(expense_documents: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []

    for doc in expense_documents or []:
        line_item_groups = _safe_get(doc, "line_item_groups", "LineItemGroups", default=[]) or []
        for group in line_item_groups:
            line_items = _safe_get(group, "line_items", "LineItems", default=[]) or []
            for li in line_items:
                fields = _safe_get(li, "line_item_expense_fields", "LineItemExpenseFields", default=[]) or []
                item: Dict[str, Any] = {}
                for field in fields:
                    field_type = _safe_get(_safe_get(field, "type", "Type", default={}), "text", "Text", default="")
                    value_obj = _safe_get(field, "value_detection", "ValueDetection", default={})
                    value = _safe_get(value_obj, "text", "Text", default=None)
                    if not field_type:
                        continue
                    key = str(field_type).lower().replace(" ", "_")
                    item[key] = value
                if item:
                    items.append(item)

    return items


def extract_invoice_fields(image_bytes: bytes) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line items from an invoice using Amazon Textract AnalyzeExpense.

    Requires:
        boto3
        AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY configured in environment or default AWS credentials chain.
    """
    import boto3  # provider-identifying signal: Amazon Textract via boto3

    textract = boto3.client("textract", region_name=os.getenv("AWS_REGION", "us-east-1"))
    response = textract.analyze_expense(Document={"Bytes": image_bytes})

    expense_documents = response.get("ExpenseDocuments", []) or []

    vendor = None
    date = None
    total = None

    for doc in expense_documents:
        summary_fields = _safe_get(doc, "summary_fields", "SummaryFields", default=[]) or []
        for field in summary_fields:
            field_type = _safe_get(_safe_get(field, "type", "Type", default={}), "text", "Text", default="")
            value_obj = _safe_get(field, "value_detection", "ValueDetection", default={})
            value = _safe_get(value_obj, "text", "Text", default=None)

            normalized = str(field_type).lower()
            if vendor is None and normalized in {"vendor_name", "merchant_name", "supplier_name"}:
                vendor = value
            elif date is None and normalized in {"invoice_receipt_date", "transaction_date", "due_date", "invoice_date"}:
                date = value
            elif total is None and normalized in {
                "total",
                "amount_due",
                "invoice_total",
                "subtotal",
                "grand_total",
                "amount_paid",
            }:
                total = value

    line_items = _extract_line_items(expense_documents)

    if total is not None:
        parsed_total = _to_number(total)
        if parsed_total is not None:
            total = parsed_total

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
        "raw": response,
    }
